export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-str-0001", "section": "service", "who": "reader", "text": "В НЕДЕЛЮ ВАИЙ НА ВЕЧЕРНЕ На"},
  {"id": "ru-str-0002", "section": "service", "who": "reader", "text": "Господи воззвах:"},
  {"id": "ru-str-0003", "section": "service", "who": "rubric", "text": "стихиры на 6; и поем три самогласна, повторяя их, глас 8:"},
  {"id": "ru-str-0004", "section": "service", "who": "reader", "text": "Радуйся и веселись град Сион, / ликуй и торжествуй Церковь Божия! / Ибо вот, пришел Царь Твой праведный, / восседающий на молодом осле / и детьми приветствуемый в песни: / «Осанна в вышних, благословен Ты, / имеющий милосердие безмерное, помилуй нас!» (2)"},
  {"id": "ru-str-0005", "section": "service", "who": "reader", "text": "Пришел Спаситель в сей день во град Иерусалим, / чтобы исполнить Писание, / и все взяли в руки пальмовые ветви / и одежды расстилали перед Ним, / зная, что Он – Бог наш, / Которому Херувимы взывают непрестанно: / «Осанна в вышних, благословен Ты, / имеющий милосердие безмерное, помилуй нас!» (2)"},
  {"id": "ru-str-0006", "section": "service", "who": "reader", "text": "На Херувимах Носимый / и воспеваемый Серафимами, / Ты, Благой, воссел на молодом осле, как Сын Давидов, / и дети воспевали Тебя, как подобает славить Бога, / Иудеи же поносили беззаконно. / Сидение же на необъезженном осленке / прообразовало, что безудержные язычники / от неверия к вере изменяются. / Слава Тебе, Христе, / Единый Милостивый и Человеколюбец! (2)"},
  {"id": "ru-str-0007", "section": "service", "who": "reader", "text": "Слава: Радуйся и веселись град Сион, / ликуй и торжествуй Церковь Божия! / Ибо вот, пришел Царь Твой праведный, / восседающий на молодом осле / и детьми приветствуемый в песни: / «Осанна в вышних, благословен Ты, / имеющий милосердие безмерное, помилуй нас!»"},
  {"id": "ru-str-0008", "section": "service", "who": "reader", "text": "И ныне: На Херувимах Носимый / и воспеваемый Серафимами, / Ты, Благой, воссел на молодом осле, как Сын Давидов, / и дети воспевали Тебя, как подобает славить Бога, / Иудеи же поносили беззаконно. / Сидение же на необъезженном осленке / прообразовало, что безудержные язычники / от неверия к вере изменяются. / Слава Тебе, Христе, / Единый Милостивый и Человеколюбец!"},
  {"id": "ru-str-0009", "section": "service", "who": "rubric", "text": "Вход. Прокимен дня:"},
  {"id": "ru-str-0010", "section": "service", "who": "reader", "text": "Благословляйте ныне:"},
  {"id": "ru-str-0011", "section": "service", "who": "reader", "text": "На стиховне стихиры самогласны, глас 2:"},
  {"id": "ru-str-0012", "section": "service", "who": "reader", "text": "От побегов пальмовых и ветвей / как от Божественного праздника / к иному Божественному празднику прейдя, / к священному страстей Христовых таинству спасительному, / соберемся верные, / и взором последуем за Ним, / за нас терпящим страдание добровольное, / и песнь подобающую Ему / благодарственно воспоем, взывая: / «Милосердия источник и пристань спасения, / Господи слава Тебе!» Стих:"},
  {"id": "ru-str-0013", "section": "service", "who": "reader", "text": "Воспойте Господу песнь новую, / ибо дивное сотворил Господь. Пс 97:1А Глас 3:"},
  {"id": "ru-str-0014", "section": "service", "who": "reader", "text": "Страшно впасть в руки Бога живого: / Он — судия движений и мыслей сердца! / Да не войдет никто, испытывающий веру непорочную, / но в кротости и страхе ко Христу приступим, / чтобы милость получить и обрести благодать / для благовременной помощи. Стих:"},
  {"id": "ru-str-0015", "section": "service", "who": "reader", "text": "Увидели все концы земли / спасение Бога нашего. Пс 97: 3В Глас 7:"},
  {"id": "ru-str-0016", "section": "service", "who": "reader", "text": "Синагога лукавая и прелюбодейная, / верности своему Мужу не сохранившая! / Что держишься Завета, / которого не стала наследницей? / Что хвалишься Отцом, Сына отвергшая? / Не приняла Ты пророков, о Сыне возвестивших! / Хотя бы детей своих устыдись, так взывающих: / «Осанна Сыну Давидову, / благословен Грядущий во имя Господне!»"},
  {"id": "ru-str-0017", "section": "service", "who": "reader", "text": "Слава, глас 2: От побегов пальмовых и ветвей / как от Божественного праздника / к иному Божественному празднику прейдя, / к священному страстей Христовых таинству спасительному, / соберемся верные, / и взором последуем за Ним, / за нас терпящим страдание добровольное, / и песнь подобающую Ему / благодарственно воспоем, взывая: / «Милосердия источник и пристань спасения, / Господи слава Тебе!»"},
  {"id": "ru-str-0018", "section": "service", "who": "reader", "text": "И ныне, глас 3: Страшно впасть в руки Бога живого: / Он — судия движений и мыслей сердца! / Да не войдет никто, испытывающий веру непорочную, / но в кротости и страхе ко Христу приступим, / чтобы милость получить и обрести благодать / для благовременной помощи."},
  {"id": "ru-str-0019", "section": "service", "who": "reader", "text": "Ныне отпускаешь: Трисвятое, по"},
  {"id": "ru-str-0020", "section": "service", "who": "reader", "text": "Отче наш:"},
  {"id": "ru-str-0021", "section": "service", "who": "rubric", "text": "И обычное окончание утрени по уставу св. Четыредесятницы с тропарями"},
  {"id": "ru-str-0022", "section": "service", "who": "reader", "text": "Богородица Дева, радуйся: и поклонами."},
  {"id": "ru-str-0023", "section": "service", "who": "reader", "text": "Отпуст: Господь, идущий на добровольное страдание нашего ради спасения, – Христос истинный Бог наш, – по молитвам пречистой Своей Матери, святых славных и всехвальных Апостолов, святых и праведных Богоотцов Иоакима и Анны и всех святых, помилует и спасет нас, как благой и Человеколюбец."},
  {"id": "ru-str-0024", "section": "service", "who": "rubric", "text": "Тот же отпуст произносится в понедельник, вторник и среду."},
  {"id": "ru-str-0025", "section": "service", "who": "reader", "text": "В НЕДЕЛЮ ВАИЙ НА ПОВЕЧЕРИИ"},
  {"id": "ru-str-0026", "section": "service", "who": "rubric", "text": "Повечерие совершатся малое и на нем поется трипеснец преподобного Андрея Критского. Ирмосы исполняются дважды, а тропари — сколько их есть. В конце поют ирмос оба хора вместе. Также и в прочие дни Страстной седмицы на повечериях. Глас 8."},
  {"id": "ru-str-0027", "section": "service", "who": "reader", "text": "Песнь 1 Ирмос:"},
  {"id": "ru-str-0028", "section": "service", "who": "reader", "text": "Сокрушившему врага в битве мышцею Своею / и проведшему Израиль через Красное море, / воспоем Ему, как Избавителю нашему Богу, / ибо Он прославился!"},
  {"id": "ru-str-0029", "section": "service", "who": "reader", "text": "Целомудрию Иосифа подражать будем, верные; / познаем Почтившего разумом человеческое естество, / проводя жизнь со всякой осторожностью, / в деятельной добродетели."},
  {"id": "ru-str-0030", "section": "service", "who": "reader", "text": "Неисполнение добрых дел уподобляет нас смоковнице: / уклонимся же от того, / чтобы не иссохнуть, как некогда она, / синагогу, одними листьями покрытую предначертавшая."},
  {"id": "ru-str-0031", "section": "service", "who": "reader", "text": "Образ Владыки начертывая, Иосиф / в ров ввергается, родными продается, / все терпит, славный, / как поистине прообраз Христов."},
  {"id": "ru-str-0032", "section": "service", "who": "reader", "text": "Бесплодия смоковницы избегнув, братия, / уразумеем этот пример, / чтобы не иссохнуть, как она тогда, / когда, испытывая голод, Человеколюбец / к ней на пути в город подошел."},
  {"id": "ru-str-0033", "section": "service", "who": "reader", "text": "Иисус, спеша за мир пострадать по Своей воле, / идет с учениками Своими во град Иерусалим / на добровольное страдание, / которое Он пришел претерпеть."},
  {"id": "ru-str-0034", "section": "service", "who": "reader", "text": "Присоединившись к Господу, / все претерпеть стремящемуся, / готовы будем к глумлению над собой, / к оплеванию, к осмеянию (и к унижению), / чтобы с Его пречистым страданием / вместе прославиться, верные."},
  {"id": "ru-str-0035", "section": "service", "who": "reader", "text": "Страсти страданиями исцеляет Пострадавший за нас: / ибо Он по воле Своей принимает / в свойственном нам человеческом естестве / Свои животворящие страсти, / чтобы мы спаслись."},
  {"id": "ru-str-0036", "section": "service", "who": "reader", "text": "Слава: Трех Безначальных славлю, / воспеваю Трех Святых, / проповедую Трех равно вечных во едином существе; / ибо во Отце, Сыне и Духе / прославляется единый Бог."},
  {"id": "ru-str-0037", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Жезл Моисеев и жезл Ааронов / необычайное превращение претерпели / и послужили промыслу, превышающему ум; / чрево же Твое, Божия Родительница, / впервые являет небывалое рождество!"},
  {"id": "ru-str-0038", "section": "service", "who": "reader", "text": "Седален, глас 4"},
  {"id": "ru-str-0039", "section": "service", "who": "reader", "text": "Вина смоковницы да не падет на тебя, душа, / но постарайся произвести из борозд сердца / добрые плоды Создателю своему Христу, / в покаянии их Ему принося."},
  {"id": "ru-str-0040", "section": "service", "who": "reader", "text": "Песнь 8 Ирмос:"},
  {"id": "ru-str-0041", "section": "service", "who": "reader", "text": "На горе святой Прославившегося / и огнем в кусте терновом / Моисею Приснодевы таинство явившего — / Господа пойте и превозносите во все века."},
  {"id": "ru-str-0042", "section": "service", "who": "reader", "text": "Целомудрием украсив жизнь / и рассудительностию сохранив веру, / праведность нрава покажем, / чтобы с мужеством следуя за Христом, / с Ним сораспяться."},
  {"id": "ru-str-0043", "section": "service", "who": "reader", "text": "Другую Еву встретив в египтянке, / не склонился к неправедному делу патриарх Иосиф, / но устоял, как некий алмаз, / не уловленный страстями греховными."},
  {"id": "ru-str-0044", "section": "service", "who": "reader", "text": "Проходя жизненными путями, Спаситель мой, / Ты голод испытал по Своей воле, / стремясь к спасению всех; / ибо того Ты алкал: / обращения от Тебя удалившихся."},
  {"id": "ru-str-0045", "section": "service", "who": "reader", "text": "Праотец, вкусив от древа, / когда осознал, что наг он и постыжен, / листья смоковницы взяв, опоясася: / и тем прообразовал синагогу, / себя обнажившую отвержением Христа."},
  {"id": "ru-str-0046", "section": "service", "who": "reader", "text": "Готовься, душа прежде исхода, / к жизни тамошней снаряжай себя; / и со Христом, стремящимся за тебя претерпеть страдание, / поспеши пострадать, и быть распятым, и умереть, / чтобы Он прославил тебя."},
  {"id": "ru-str-0047", "section": "service", "who": "reader", "text": "Как не содрогнется смерть, Спаситель мой? / Как не убоится ад, встречая Тебя, / по благоволению Своему к страданию спешащего, / и видя Тебя, праведного, / за неправедных пострадать пришедшего?"},
  {"id": "ru-str-0048", "section": "service", "who": "reader", "text": "Воскресение Лазаря видевшие: / Иудеи, священники и левиты, / устроив по зависти сговор о предательстве коварном, / Христа на смерть предавали Пилату."},
  {"id": "ru-str-0049", "section": "service", "who": "reader", "text": "Агница Твоя, и Раба, и Дева, / видя Тебя, устремляющегося к страданию, / и душу за нас полагающего доброго Пастыря, / сердцем материнским о Тебе терзалась."},
  {"id": "ru-str-0050", "section": "service", "who": "reader", "text": "Благословим Отца, и Сына, и Святого Духа, Господа. Троичен:"},
  {"id": "ru-str-0051", "section": "service", "who": "reader", "text": "Как Единицу Существом воспеваю Тебя, / как Троицу Лиц Тебя почитаю, / Отче, и Сын, и Дух Всесвятой: / безначальную власть Твоего Царства я славлю вовеки."},
  {"id": "ru-str-0052", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Молит Тебя, Христе, Богородица, / умоляет учеников (Твоих) сонм: / Твой мир даруй миру Твоему, / и сострадание Твое являй нам обильно вовеки."},
  {"id": "ru-str-0053", "section": "service", "who": "reader", "text": "Хвалим, благословляем, поклоняемся Господу, воспевая и превознося Его во все века. Ирмос:"},
  {"id": "ru-str-0054", "section": "service", "who": "reader", "text": "На горе святой Прославившегося:"},
  {"id": "ru-str-0055", "section": "service", "who": "reader", "text": "Песнь 9 Ирмос:"},
  {"id": "ru-str-0056", "section": "service", "who": "reader", "text": "Чуждое матерям девство / и несвойственное девам деторождение – / то и другое совершилось на Тебе, Богородица: / потому все мы, племена земные, / непрестанно Тебя величаем."},
  {"id": "ru-str-0057", "section": "service", "who": "reader", "text": "Чуждо нечестивым целомудрие, / и несвойственно праведникам законопреступление; / Иосиф же великий уклонился от греха / и сделался образом целомудрия / и подобием воистину Христовым."},
  {"id": "ru-str-0058", "section": "service", "who": "reader", "text": "Чужда беззаконникам справедливость, / и несвойственно неверным боговедение; / Иудеи же это отвергли по беззаконию. / Потому и сами унаследовали / как смоковница проклятие."},
  {"id": "ru-str-0059", "section": "service", "who": "reader", "text": "Взалкал человеческого спасения / Христос, хлеб жизни истинный и Бог мой. / И, как прежде смоковницу, бесплодную синагогу, / покрывающуюся листьями закона, / когда увидел, проклял."},
  {"id": "ru-str-0060", "section": "service", "who": "reader", "text": "Подзаконное бесплодие Ты проклял, / производящее как листья / лишь буквы темное познание, / плодов же дел не имеющее по причине беззакония; / нас же всех, сынов благодати, / Спаситель, благослови."},
  {"id": "ru-str-0061", "section": "service", "who": "reader", "text": "Прежде жезл Моисея превратился в змею, / а жезл Аарона, бесплодный и высохший, / стал зеленеть и листья пустил; / беззаконная же синагога обратилась / в бесплодную смоковницу."},
  {"id": "ru-str-0062", "section": "service", "who": "reader", "text": "Готовь, Иудея священников своих, / снаряжай руки к богоубийству: / ибо вот, пришел кроткий и тихий к страданию, / истинный Агнец и Пастырь наш — / Христос Царь Израилев."},
  {"id": "ru-str-0063", "section": "service", "who": "reader", "text": "Прими, Иудея, Царя, / ибо вот, на страдание идет Он добровольно, / чтобы пострадать и спасти непрестанно восклицающих: / «Благословен Грядущий все спасти Крестом!»"},
  {"id": "ru-str-0064", "section": "service", "who": "reader", "text": "Обратил Владыка праздники твои, Иудея, / в скорбь, по пророчеству: / ибо явилась ты убийцею Бога, / превратившего некогда скалу и утес / в источники вод и озера, / как воспевает Давид."},
  {"id": "ru-str-0065", "section": "service", "who": "reader", "text": "Слава: Чуждо для беззаконных славить / Тебя, безначальное Существо: / Отца, и Сына, и Святого Духа, / несотворенное Всевластие, / Которым держится весь мир / по мановению Его Божественного могущества."},
  {"id": "ru-str-0066", "section": "service", "who": "reader", "text": "И ныне: Мы побуждаем к ходатайству пред Тобой Богородицу: / Ее мольбами и апостолов Твоих / соделай нас, Владыка, благ Твоих общниками / и удостой, Спаситель, сияния / Воскресения Твоего."},
  {"id": "ru-str-0067", "section": "service", "who": "rubric", "text": "И снова тот же ирмос:"},
  {"id": "ru-str-0068", "section": "service", "who": "reader", "text": "Чуждое матерям девство:"},
  {"id": "ru-str-0069", "section": "service", "who": "rubric", "text": "Также и прочее, как обычно. И отпуст."},
  {"id": "ru-str-0070", "section": "service", "who": "rubric", "text": "Ведомо буди, яко в сию святую Великую седмицу единою совершаем Псалтирь, и глаголем на Утрени кафисмы три, и на часех, 3-м и 6-м, две. И совершаются в среду. В Великую же Субботу стихословятся Непорочны, в Вечернях же глаголем обычно: Ко Господу внегда скорбети ми:"},
  {"id": "ru-str-0071", "section": "service", "who": "reader", "text": "ВО СВЯТОЙ И ВЕЛИКИЙ ПОНЕДЕЛЬНИК НА УТРЕНИ"},
  {"id": "ru-str-0072", "section": "service", "who": "rubric", "text": "После шестопсалмия поем"},
  {"id": "ru-str-0073", "section": "service", "who": "reader", "text": "Аллилуия"},
  {"id": "ru-str-0074", "section": "service", "who": "rubric", "text": "на глас 8, и трижды тропарь."},
  {"id": "ru-str-0075", "section": "service", "who": "reader", "text": "Тропарь, глас 8 Вот, Жених приходит в полночь, / и блажен тот раб, кого найдет Он бодрствующим, / но, напротив, недостоин тот, кого Он найдет беспечным. / Смотри же, душа моя, не будь побеждена сном, да не будешь смерти предана, / и заключена вне Царствия, / но воспрянь, взывая: / Свят, Свят, Свят Ты, Боже, / по молитвам Богородицы помилуй нас! (3)"},
  {"id": "ru-str-0076", "section": "service", "who": "rubric", "text": "Также обычное стихословие."},
  {"id": "ru-str-0077", "section": "service", "who": "reader", "text": "После 1 стихословии седален, глас 1"},
  {"id": "ru-str-0078", "section": "service", "who": "reader", "text": "Страдания священные в нынешний день, / как светила спасительные восходят миру: / ибо Христос спешит пострадать по благости; / все Держащий в руке Своей / благоволит быть повешенным на Древе, / чтобы спасти человека."},
  {"id": "ru-str-0079", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-str-0080", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-str-0081", "section": "service", "who": "reader", "text": "После 2 стихословии седален, глас 1"},
  {"id": "ru-str-0082", "section": "service", "who": "reader", "text": "Невидимый Судия! / Как Ты видим был во плоти, / и как приходишь, чтобы быть убитым мужами беззаконными, / Своим страданием осуждая наше осуждение? / Потому хвалу, величие и славу воссылая власти Твоей, Слово, / согласно их приносим."},
  {"id": "ru-str-0083", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-str-0084", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-str-0085", "section": "service", "who": "reader", "text": "После 3 стихословии седален, глас 8"},
  {"id": "ru-str-0086", "section": "service", "who": "reader", "text": "Страстей Господних начатки / настоящий день блистательно приносит. / Придите же, любящие праздновать, / встретим его песнопениями: / ибо Создатель приходит Крест принять, / дознания и раны на суде Пилата. / Оттого, получив от раба удар в лицо, / все переносит, чтобы человека спасти. / Потому возгласим Ему: / «Человеколюбивый Христе Боже, / даруй согрешений отпущение / поклоняющимся с верою пречистым страданиям Твоим!»"},
  {"id": "ru-str-0087", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-str-0088", "section": "service", "who": "rubric", "text": "и повторяем то же."},
  {"id": "ru-str-0089", "section": "service", "who": "reader", "text": "Евангелие от Матфея зачало 84Б"},
  {"id": "ru-str-0090", "section": "service", "who": "reader", "text": "В то время, возвращаясь в город, Иисус ощутил голод и, увидев при дороге одинокую смоковницу, подошел к ней и ничего не нашел на ней, кроме одних только листьев. И говорит ей: да не будет от тебя плода вовек. И смоковница сразу засохла. И увидев, ученики с удивлением говорили: как это сразу засохла смоковница? Иисус же ответил им: истинно говорю вам: если будете иметь веру и не усомнитесь, сделаете не только то, что было со смоковницей, но, если и горе этой скажете: «сойди с твоего места и бросься в море», – будет. И все, чего ни попросите в молитве с верою, получите. И когда Он пришел в храм, подошли к Нему, пока Он учил, первосвященники и старейшины народа и спросили: какою властью Ты это делаешь, и кто Тебе дал эту власть? Иисус же ответил им: спрошу вас и Я об одном: если скажете Мне, то и Я скажу вам, какою властью это делаю. Крещение Иоанново откуда было: с неба или от людей? Они же рассуждали между собой: если скажем: «с неба», Он скажет нам: «почему же вы не поверили ему?» Если же скажем: «от людей», – боимся толпы, ибо все считают Иоанна пророком. И они сказали Иисусу в ответ: не знаем. Сказал им и Он: и Я вам не скажу, какою властью это делаю. А как вам кажется? У человека было двое детей; и он, подойдя к первому, сказал «дитя мое, иди сегодня, работай в винограднике». Он же ответил: «Иду, господин» и не пошел. И подойдя ко второму, он сказал то же. И тот ответил: «не хочу», а после раскаялся и пошел. Кто из двух исполнил волю отца? Они говорят: последний. Говорит им Иисус: истинно говорю вам: мытари и блудницы идут впереди вас в Царство Божие. Ибо пришел к вам Иоанн путем праведности, и вы не поверили ему, а мытари и блудницы поверили ему, вы же, увидев, не раскаялись и после, чтобы поверить ему. Выслушайте другую притчу. Был человек хозяин дома, который насадил виноградник и стеной его обнес, и выкопал в нем точило, и построил башню, и сдал его виноградарям, и уехал. Когда же приблизилось время плодов, послал он своих рабов к виноградарям взять плоды свои; и взяли виноградари рабов его, кого прибили, кого убили, кого камнями побили. Снова послал он других рабов, в большем числе, чем первых; и поступили с ними так же. Наконец, послал он к ним сына своего, говоря: «устыдятся сына моего». Виноградари же, увидев сына, сказали друг другу: «это наследник; давайте, убьем его и завладеем наследством его». И взяв его, выбросили вон из виноградника и убили. Итак, когда придет господин виноградника, что сделает он с виноградарями теми? Говорят Ему: предаст их, как злодеев, заслуженной ими злой смерти и виноградник сдаст другим виноградарям, которые будут отдавать ему плоды в свои сроки. Говорит им Иисус: никогда не читали вы в Писаниях: «Камень, который отвергли строители, он сделался главою угла: от Господа это, и удивительно в глазах наших»? Поэтому говорю вам: Царство Божие будет отнято у вас и дано приносящему его плоды народу. Мф 21:18–43"},
  {"id": "ru-str-0091", "section": "service", "who": "rubric", "text": "Посем псалом 50 и молитва"},
  {"id": "ru-str-0092", "section": "service", "who": "reader", "text": "Спаси, Боже, народ Твой: Господи, помилуй (12)"},
  {"id": "ru-str-0093", "section": "service", "who": "reader", "text": "."},
  {"id": "ru-str-0094", "section": "service", "who": "reader", "text": "Трипеснец, господина Космы Маюмского, глас 2 Его акростих:"},
  {"id": "ru-str-0095", "section": "service", "who": "reader", "text": "Ти девтера , что значит:"},
  {"id": "ru-str-0096", "section": "service", "who": "reader", "text": "Во второй день. (то есть"},
  {"id": "ru-str-0097", "section": "service", "who": "reader", "text": "В понедельник"},
  {"id": "ru-str-0098", "section": "service", "who": "rubric", "text": "). Ирмосы исполняем дважды, тропари же на 12. Припев:"},
  {"id": "ru-str-0099", "section": "service", "who": "reader", "text": "Слава Тебе Боже наш, слава Тебе."},
  {"id": "ru-str-0100", "section": "service", "who": "rubric", "text": "[Этот же припев во всю седмицу]. В конце же ирмос поют оба хора вместе."},
  {"id": "ru-str-0101", "section": "service", "who": "reader", "text": "Песнь 1 Ирмос:"},
  {"id": "ru-str-0102", "section": "service", "who": "reader", "text": "Непроходимое волнующееся море / Божественным Своим повелением Осушившему, / и народ Израильский чрез него пешком проведшему, / Господу воспоем; / ибо славно Он прославился."},
  {"id": "ru-str-0103", "section": "service", "who": "reader", "text": "Неизреченно Слова Божия нисхождение: / тот же Христос — Сам Бог и вместе человек; / Божество Свое не считая для Себя хищением, / Он, образ раба приняв, являет это ученикам; / ибо славно Он прославился."},
  {"id": "ru-str-0104", "section": "service", "who": "reader", "text": "Послужить Я Сам пришел Адаму обнищавшему, / в чей образ облекся добровольно / Я – Создатель, богатый Божеством, / и положить душу Мою за него во искупление / хочу Я, бесстрастный по Божеству."},
  {"id": "ru-str-0105", "section": "service", "who": "reader", "text": "Кондак, глас 8"},
  {"id": "ru-str-0106", "section": "service", "who": "reader", "text": "Иаков скорбел о потере Иосифа, / а тот, доблестный восседал на колеснице, как царь почитаемый; / ибо не став однажды рабом наслаждений с египтянкой, / он обрел за это славу от Видящего человеческие сердца / и Дающего венец нетленный. Икос:"},
  {"id": "ru-str-0107", "section": "service", "who": "reader", "text": "К скорби ныне прибавим скорбь, / и прольем слезы с Иаковом, / оплакивая Иосифа славного и целомудренного, / проданного в рабство телом, но душу непорабощенной сохранившего / и власть над всем Египтом получившего: / ибо Бог подает рабам Своим / венец нетленный. Синаксарий."},
  {"id": "ru-str-0108", "section": "service", "who": "reader", "text": "Песнь 8 Ирмос:"},
  {"id": "ru-str-0109", "section": "service", "who": "reader", "text": "Устрашился непорочного тела чистых отроков, / сообразного душе, / и отступил огонь неукротимый, / вскормленный безмерным веществом; / а когда обессилело всегда живое пламя, / непрестанная воспевалась песнь: / «Все творения, Господа воспевайте / и превозносите во все века!»"},
  {"id": "ru-str-0110", "section": "service", "who": "reader", "text": "«В вас тогда все узнают Моих учеников, / если заповеди Мои соблюдете», – / говорит Спаситель друзьям Своим, / на страдание шествуя; – / «мир имейте между собою и со всеми, / и, смиренно мудрствуя, возвышайтесь; / и, познав Господа во Мне, / воспевайте и превозносите во все века!»"},
  {"id": "ru-str-0111", "section": "service", "who": "reader", "text": "«Делом чуждого вам обычая языческого / пусть будет господство над собратьями. / Ибо это не Мой жребий, / но владычество Мое – свободное произволение. / Итак, кто между вами желает быть перед другими предпочтенным, / да будет из всех последним; / и, познав Господа во Мне, / воспевайте и превозносите во все века!»"},
  {"id": "ru-str-0112", "section": "service", "who": "reader", "text": "Хвалим, благословляем, поклоняемся Господу, воспевая и превознося Его во все века."},
  {"id": "ru-str-0113", "section": "service", "who": "rubric", "text": "И снова ирмос."},
  {"id": "ru-str-0114", "section": "service", "who": "reader", "text": "Честью высшую Херувимов: не поем."},
  {"id": "ru-str-0115", "section": "service", "who": "reader", "text": "Песнь 9 Ирмос:"},
  {"id": "ru-str-0116", "section": "service", "who": "reader", "text": "Возвеличил Ты, Христе, родившую Тебя Богородицу, / от Которой Ты, Создатель наш, / облекся телом, нам во всем подобным, / во искупление наших грехов неведения; / Ее блаженной именуя, мы, все роды, / Тебя величаем."},
  {"id": "ru-str-0117", "section": "service", "who": "reader", "text": "«Всякую нечистоту страстную отвергнув, / усвойте понимание разумное, / достойное Божественного Царства, / в котором вы прославитесь, сияя яснее солнца», / – предсказал Ты, всех Премудрость, / Твоим апостолам."},
  {"id": "ru-str-0118", "section": "service", "who": "reader", "text": "«Взирая на Меня», – сказал Ты, Господи, / ученикам Своим, – не высокомудрствуйте, / но следуйте за мыслями смиренными; / вы пьете чашу Мою, которую Я пью; / потому в Царстве Отца Моего / со Мною прославитесь. Также ирмос:"},
  {"id": "ru-str-0119", "section": "service", "who": "reader", "text": "Возвеличил Ты, Христе:"},
  {"id": "ru-str-0120", "section": "service", "who": "rubric", "text": "И земной поклон."},
  {"id": "ru-str-0121", "section": "service", "who": "reader", "text": "Ексапостиларий Чертог Твой вижу я, Спаситель мой, украшенным, / но одежды не имею, чтобы войти в него. / Сделай светлым одеяние души моей, / Податель света, и спаси меня. (3)"},
  {"id": "ru-str-0122", "section": "service", "who": "reader", "text": "На «Хвалите:» стихиры самогласны на 4, глас 1"},
  {"id": "ru-str-0123", "section": "service", "who": "reader", "text": "Господь, идя на добровольное страдание, / говорил апостолам на пути: / «Вот, мы восходим во Иерусалим, / и предан будет Сын Человеческий, как написано о Нем»!» / Давайте же и мы, очищенными мыслями / будем сопутствовать Ему, и с Ним распнемся, / и умертвим себя ради Него для житейских наслаждений, / чтобы с Ним и ожить, и услышать Его, возглашающего: / «Уже не в земной Иерусалим восхожу, чтобы пострадать, / но ко Отцу Моему и Отцу вашему, / и к Богу Моему и Богу вашему, / и вас с Собою вознесу в горний Иерусалим, / в Царство Небесное!» (2) Глас 5:"},
  {"id": "ru-str-0124", "section": "service", "who": "reader", "text": "Достигнув, верные, / спасительного страдания Христа Бога, / неизреченное Его долготерпение прославим, / чтобы Он по милосердию Своему / воздвиг с Собой и нас, умерщвленных грехом, / как Благой и Человеколюбец. (2)"},
  {"id": "ru-str-0125", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тот же: Господи, шествуя на страдание / и утверждая Своих учеников, / Ты, призвав их, говорил им наедине: / «Как вы слов Моих не помните, / тех, что Я прежде вам сказал, / что никакому Пророку, как написано, / невозможно вне Иерусалима быть убитым? / Ныне же настало время, / о котором Я вам говорил: / ибо вот, Я предаю Себя в руки грешников на поругание; / и они, ко кресту Меня пригвоздив, / и погребению предав, / презренным сочтут, как мертвого. / Однако дерзайте: ибо Я восстану на третий день / на радость верным и в жизнь вечную!»"},
  {"id": "ru-str-0126", "section": "service", "who": "reader", "text": "На стиховне самогласен, глас 5"},
  {"id": "ru-str-0127", "section": "service", "who": "reader", "text": "Не постигая несказанного таинства / промысла Твоего, Господи, / матерь сынов Зеведеевых просила у Тебя, / чтобы почести временного царства / были дарованы чадам ее; / но вместо того Ты обещал, / что чашу смертную будут пить друзья Твои, / ту чашу, о которой Ты говорил, / что Сам прежде них будешь пить ее / для очищения нас от грехов. / Потому мы Тебе взываем: / «Спасение душ наших, слава Тебе!» Стих:"},
  {"id": "ru-str-0128", "section": "service", "who": "reader", "text": "Насытились мы рано утром милостью Твоею, Господи, и возрадовались и возвеселились. Во все дни наши возвеселились: за дни, в которые Ты смирил нас, за годы, в которые мы видели злое. И воззри на рабов Твоих и на дела Твои, / и укажи путь сынам их."},
  {"id": "ru-str-0129", "section": "service", "who": "reader", "text": "Господи, совершеннейшим образом мудрствовать / наставляя учеников Своих, / ты внушал им язычникам не уподобляться / в желании начальствовать над меньшими: / «Не так да будет у вас, Моих учеников, / ибо Сам Я – нищий по воле Своей. / Так, первый среди вас да будет всем слуга; / начальствующий же – как подначальный, / а предпочтенный – как последний. / Ведь Сам Я пришел обнищавшему Адаму послужить, / и отдать душу Мою во искупление многих, / взывающих Мне: Слава Тебе!» Стих:"},
  {"id": "ru-str-0130", "section": "service", "who": "reader", "text": "И да будет сияние Господа Бога нашего на нас, и дела рук наших исправь у нас, / и дело рук наших исправь. Глас 8:"},
  {"id": "ru-str-0131", "section": "service", "who": "reader", "text": "Устрашившись наказания, братия, / иссохшей за бесплодие смоковницы, / плоды достойные покаяния принесем Христу, / подающему нам великую милость."},
  {"id": "ru-str-0132", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тот же: Вторую Еву в египтянке обретя, / старался змий ее речами льстивыми соблазнить Иосифа; / но он, оставив одежду, бежал от греха, / и, нагой, не стыдился, как первозданный до ослушания. / Его мольбами, Христе, помилуй нас. Также:"},
  {"id": "ru-str-0133", "section": "service", "who": "reader", "text": "Благо есть:"},
  {"id": "ru-str-0134", "section": "service", "who": "rubric", "text": "И окончание утрени по чину Великой Четыредесятницы."},
  {"id": "ru-str-0135", "section": "service", "who": "reader", "text": "Отпуст: Господь, идущий на добровольное страдание нашего ради спасения, – Христос истинный Бог наш, – по молитвам пречистой Своей Матери, святых славных и всехвальных Апостолов, святых и праведных Богоотцов Иоакима и Анны и всех святых, помилует и спасет нас, как благой и Человеколюбец."},
  {"id": "ru-str-0136", "section": "service", "who": "rubric", "text": "На первом и девятом часе кафизм нет. Третий же час и шестый с кафизмами. На часах третьем, шестом и девятом в Понедельник во Вторник и в Среду читается Четвероевангелие. На третьем часе после"},
  {"id": "ru-str-0137", "section": "service", "who": "reader", "text": "Богородица, Ты лоза истинная:"},
  {"id": "ru-str-0138", "section": "service", "who": "rubric", "text": "выносится св. Евангелие с двумя возжженными светильниками и полагается на аналое. Священник кадит весь храм; на шестом же часе — только Евангелие. На девятом — снова весь храм. По окончании же чтения возглашаем:"},
  {"id": "ru-str-0139", "section": "service", "who": "priest", "text": "Господь Бог благословен:"},
  {"id": "ru-str-0140", "section": "service", "who": "rubric", "text": "И прочее последование. Кондак дня:"},
  {"id": "ru-str-0141", "section": "service", "who": "priest", "text": "Иаков скорбел о потере Иосифа:"},
  {"id": "ru-str-0142", "section": "service", "who": "rubric", "text": "И обычные поклоны."},
  {"id": "ru-str-0143", "section": "service", "who": "priest", "text": "НА ШЕСТОМ ЧАСЕ"},
  {"id": "ru-str-0144", "section": "service", "who": "priest", "text": "Придите, поклонимся:"},
  {"id": "ru-str-0145", "section": "service", "who": "rubric", "text": "трижды и обычные псалмы: Кафизма 8. Также тропарь:"},
  {"id": "ru-str-0146", "section": "service", "who": "priest", "text": "В день шестой и в шестой же час:"},
  {"id": "ru-str-0147", "section": "service", "who": "rubric", "text": "и Богородичен:"},
  {"id": "ru-str-0148", "section": "service", "who": "priest", "text": "Нет у нас дерзновения: и поклоны 3."},
  {"id": "ru-str-0149", "section": "service", "who": "priest", "text": "Тропарь пророчества, глас 6"},
  {"id": "ru-str-0150", "section": "service", "who": "priest", "text": "С душою сокрушенною мы припадаем к Тебе, / и молим Тебя, Спаситель мира, / ибо Ты – Бог кающихся."},
  {"id": "ru-str-0151", "section": "service", "who": "priest", "text": "Слава, и ныне:"},
  {"id": "ru-str-0152", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-str-0153", "section": "service", "who": "priest", "text": "Прокимен, глас 4"},
  {"id": "ru-str-0154", "section": "service", "who": "priest", "text": "Когда возвратил Господь / плен Сиона. Стих:"},
  {"id": "ru-str-0155", "section": "service", "who": "priest", "text": "Тогда исполнились радости уста наши. Пс 125:1А, 2А"},
  {"id": "ru-str-0156", "section": "service", "who": "priest", "text": "Пророчества Иезекииля чтение"},
  {"id": "ru-str-0157", "section": "service", "who": "priest", "text": "Было в тридцатый год, в четвертый месяц, в пятый день месяца, и был я среди пленников при реке Ховар, и отверзлись небеса, и я узрел видение Божие. В пятый день месяца – это пятый год пленения царя Иоакима, – и было слово Господне к Иезекиилю, сыну Вузия, священнику, в земле Халдееев, при реке Ховар; и была на мне рука Господня. И я увидел: и вот, ветер поднимающийся шел от севера, и облако великое в нем, и сияние вокруг него, и огонь блистающий; а в средине его как бы вид янтаря посреди огня; и сияние в нем, и в середине как бы подобие четырех животных. И вот видение их: (как бы) подобие человека у них; и четыре лица у каждого, и четыре крыла у каждого; и голени их прямые, и оперены ноги их, и искры – как блистающая медь, и легки крылья их. И руки человеческие – из-под крыльев их, на четырех сторонах их; и лица их, и крылья их четырех соприкасались одно с другим; и лица их четырех не оборачивались во время шествия их; каждое по направлению лица своего шло. И подобие лиц их: лицо человека, и лицо льва справа у всех четырех, и лицо тельца слева у всех четырех, и лицо орла у всех четырех. И (лица их и) крылья их простерты вверх у всех четырех; у каждого два соединялись друг с другом, а два покрывали сверху тела их. И каждое по направлению лица своего шло; куда пойдет Дух, они шли и не оборачивались. И посреди животных – вид как бы углей, огнем горящих, как вид лампад, кружащихся между животными, и сияние огня, и из огня исходила (как бы) молния. И животные бежали и поворачивали, как вид россыпи искр *"},
  {"id": "ru-str-0158", "section": "service", "who": "priest", "text": ". И я увидел: и вот по одному колесу на земле возле четырех животных. И вид колес – как вид топаза **"},
  {"id": "ru-str-0159", "section": "service", "who": "priest", "text": "; и подобие, и устройство их – одно у всех четырех; и устройство их было, как будто бы колесо находилось в колесе. На четыре стороны свои они шли и не поворачивали во время шествия их – даже ободья их; и высота была у них. И я увидел их: и ободья их полны глаз кругом у всех четырех! И во время шествия животных, шли и колеса возле них; и при подъеме животных от земли, поднимались и колеса. Где облако, там был и Дух, побуждающий идти: шли животные, и колеса поднимались с ними, ибо Дух Жизни был в колесах. Иез 1:1–20"},
  {"id": "ru-str-0160", "section": "service", "who": "rubric", "text": "*с греч. букв.:"},
  {"id": "ru-str-0161", "section": "service", "who": "priest", "text": "вид Везека"},
  {"id": "ru-str-0162", "section": "service", "who": "rubric", "text": "**с греч. букв.:"},
  {"id": "ru-str-0163", "section": "service", "who": "priest", "text": "вид фарсиса"},
  {"id": "ru-str-0164", "section": "service", "who": "priest", "text": "Прокимен, глас 4"},
  {"id": "ru-str-0165", "section": "service", "who": "priest", "text": "Если Господь не построит дома, / впустую потрудились строители. Стих:"},
  {"id": "ru-str-0166", "section": "service", "who": "priest", "text": "Если Господь не сохранит города, впустую бодрствовал страж. Пс 126:1"},
  {"id": "ru-str-0167", "section": "service", "who": "rubric", "text": "И читается Евангелие по предписанному чину. По чтении же:"},
  {"id": "ru-str-0168", "section": "service", "who": "priest", "text": "Скоро да встретит нас сострадание Твое, Господи: Трисвятое по"},
  {"id": "ru-str-0169", "section": "service", "who": "priest", "text": "Отче наш: Кондак дня."},
  {"id": "ru-str-0170", "section": "service", "who": "priest", "text": "Господи помилуй,"},
  {"id": "ru-str-0171", "section": "service", "who": "rubric", "text": "40. И прочее по обычаю, и отпуст."},
  {"id": "ru-str-0172", "section": "service", "who": "rubric", "text": "Девятый же час во все три дня без кафизмы, но с чтением Четвероевангелия: После же читаем"},
  {"id": "ru-str-0173", "section": "service", "who": "priest", "text": "Не предай нас до конца: Трисвятое по"},
  {"id": "ru-str-0174", "section": "service", "who": "priest", "text": "Отче наш: Кондак дня."},
  {"id": "ru-str-0175", "section": "service", "who": "priest", "text": "Во Царствии Твоем:"},
  {"id": "ru-str-0176", "section": "service", "who": "rubric", "text": "И прочее последование, как обычно. И начинаем Вечерню."},
  {"id": "ru-str-0177", "section": "service", "who": "priest", "text": "ВО СВЯТОЙ И ВЕЛИКИЙ ПОНЕДЕЛЬНИК НА ВЕЛИКОЙ ВЕЧЕРНЕ"},
  {"id": "ru-str-0178", "section": "service", "who": "rubric", "text": "По предначинательном псалме кафизма 18. На"},
  {"id": "ru-str-0179", "section": "service", "who": "priest", "text": "«Господи воззвах:»"},
  {"id": "ru-str-0180", "section": "service", "who": "rubric", "text": "стихиры на 10; и поем самогласны дня 4 по дважды, а два по единожды, глас 1:"},
  {"id": "ru-str-0181", "section": "service", "who": "priest", "text": "Господь, идя на добровольное страдание, / говорил апостолам на пути: / «Вот, мы восходим во Иерусалим, / и предан будет Сын Человеческий, как написано о Нем»!» / Давайте же и мы, очищенными мыслями / будем сопутствовать Ему, и с Ним распнемся, / и умертвим себя ради Него для житейских наслаждений, / чтобы с Ним и ожить, и услышать Его, возглашающего: / «Уже не в земной Иерусалим восхожу, чтобы пострадать, / но ко Отцу Моему и Отцу вашему, / и к Богу Моему и Богу вашему, / и вас с Собою вознесу в горний Иерусалим, / в Царство Небесное!» (2) Глас 5:"},
  {"id": "ru-str-0182", "section": "service", "who": "priest", "text": "Достигнув, верные, / спасительного страдания Христа Бога, / неизреченное Его долготерпение прославим, / чтобы Он по милосердию Своему / воздвиг с Собой и нас, умерщвленных грехом, / как Благой и Человеколюбец. (2)"},
  {"id": "ru-str-0183", "section": "service", "who": "priest", "text": "Господи, шествуя на страдание / и утверждая Своих учеников, / Ты, призвав их, говорил им наедине: / «Как вы слов Моих не помните, / тех, что Я прежде вам сказал, / что никакому Пророку, как написано, / невозможно вне Иерусалима быть убитым? / Ныне же настало время, / о котором Я вам сказал: / ибо вот, Я предаю Себя в руки грешников на поругание; / и они, ко кресту Меня пригвоздив, / и погребению предав, / презренным сочтут, как мертвого. / Однако дерзайте: ибо Я восстану на третий день / на радость верным и в жизнь вечную!» (2)"},
  {"id": "ru-str-0184", "section": "service", "who": "priest", "text": "Не постигая несказанного таинства / промысла Твоего, Господи, / матерь сынов Зеведеевых просила у Тебя, / чтобы почести временного царства / были дарованы чадам ее; / но вместо того Ты обещал, / что чашу смертную будут пить друзья Твои, / ту чашу, о которой Ты говорил, / что Сам прежде них будешь пить ее / для очищения нас от грехов. / Потому мы Тебе взываем: / «Спасение душ наших, слава Тебе!» (2)"},
  {"id": "ru-str-0185", "section": "service", "who": "priest", "text": "Господи, совершеннейшим образом мудрствовать / наставляя учеников Своих, / ты внушал им язычникам не уподобляться / в желании начальствовать над меньшими: / «Не так да будет у вас, Моих учеников, / ибо Сам Я – нищий по воле Своей. / Так, первый среди вас да будет всем слуга; / начальствующий же – как подначальный, / а предпочтенный – как последний. / Ведь Сам Я пришел обнищавшему Адаму послужить, / и отдать душу Мою во искупление многих, / взывающих Мне: Слава Тебе!» Глас 8:"},
  {"id": "ru-str-0186", "section": "service", "who": "priest", "text": "Устрашившись наказания, братия, / иссохшей за бесплодие смоковницы, / плоды достойные покаяния принесем Христу, / подающему нам великую милость."},
  {"id": "ru-str-0187", "section": "service", "who": "priest", "text": "Слава, и ныне, глас тот же: Вторую Еву в египтянке обретя, / старался змий ее речами льстивыми соблазнить Иосифа; / но он, оставив одежду, бежал от греха, / и, нагой, не стыдился, как первозданный до ослушания. / Его мольбами, Христе, помилуй нас."},
  {"id": "ru-str-0188", "section": "service", "who": "rubric", "text": "Вход с Евангелием. «Свет отрадный:»"},
  {"id": "ru-str-0189", "section": "service", "who": "priest", "text": "Прокимен, глас 6 Да благословит тебя Господь с Сиона, / и увидишь блага Иерусалима. Стих:"},
  {"id": "ru-str-0190", "section": "service", "who": "priest", "text": "Блаженны все боящиеся Господа, ходящие по путям Его. Пс 127:5А, 1"},
  {"id": "ru-str-0191", "section": "service", "who": "priest", "text": "1. Исхода чтение"},
  {"id": "ru-str-0192", "section": "service", "who": "priest", "text": "Это – имена сынов Израилевых, входивших в Египет вместе с Иаковом отцом их. Каждый со всем домом своим вошли: Рувим, Симеон, Левий, Иуда, Иссахар, Завулон (и) Вениамин, Дан и Неффалим, Гад и Асир, а Иосиф уже был в Египте. Было же всех душ, происшедших от [чресл] Иакова, семьдесят пять. И скончался Иосиф, и все братья его, и все поколение то; а сыны Израилевы возросли, и умножились, и многочисленны сделались, и весьма, весьма усилились, и преумножала их земля. И встал над Египтом иной царь, который не знал Иосифа. И сказал он народу своему: «Вот, народ сынов Израилевых – великое множество, и усиливается он более нас; давайте же перехитрим его, чтобы когда-нибудь он не умножился; и тогда, если случится у нас война, присоединятся и они к неприятелям, и одолев нас, выйдут из земли (нашей). И поставил он над ними начальников работ, чтобы изнуряли их работами. И построили они города укрепленные фараону: Пифо, (и) Рамесси, и Он, то есть Илиополь. Но насколько их унижали, настолько они становились многочисленны, и весьма, весьма усиливались. И боялись Египтяне сынов Израилевых. И угнетали Египтяне сынов Израилевых с насилием, и мучительной делали их жизнь в работах тяжких над глиною и изготовлением кирпичей, и во всех работах на полях – во всех работах, к которым принуждали их с насилием."},
  {"id": "ru-str-0193", "section": "service", "who": "priest", "text": "И обратился царь Египтян к повивальным бабкам Евреев – одной из них имя Сепфора, а имя второй – Фуа, и сказал им: «Когда вы повиваете у Евреянок, и будут они близки к родам, если будет мужской пол, то умертвите его, а если женский, сохраняйте его». Но повивальные бабки убоялись Бога и не сделали так, как повелел им царь Египетский; и оставляли они детей мужского пола в живых. И призвал царь Египетский повивальных бабок и сказал им: «Зачем же вы сделали это дело, и оставляете детей мужского пола в живых?» Но повивальные бабки сказали фараону: «Не (так), как женщины Египетские (женщины) еврейские; ведь они рождают прежде, чем придут к ним повивальные бабки; вот они и рождали». Бог же делал добро повивальным бабкам, а народ умножался и усиливался весьма. Исх 1:1–20"},
  {"id": "ru-str-0194", "section": "service", "who": "priest", "text": "Прокимен, глас 6"},
  {"id": "ru-str-0195", "section": "service", "who": "priest", "text": "Благословляем вас / во имя Господне. Стих:"},
  {"id": "ru-str-0196", "section": "service", "who": "priest", "text": "Много раз ополчались на меня с юности моей. Пс 128:8Б, 1А"},
  {"id": "ru-str-0197", "section": "service", "who": "priest", "text": "2. Иова чтение"},
  {"id": "ru-str-0198", "section": "service", "who": "priest", "text": "Человек некий был в земле Авситидийской, имя ему Иов; и был человек тот непорочным, справедливым, правдивым, богобоязненным, удалявшимся от всякого злого дела. Было же у него семь сыновей и три дочери. И было у него скота: овец семь тысяч, верблюдов три тысячи, пятьсот пар волов, ослиц на пастбище пятьсот и прислуга весьма многочисленная; и дела великие были у него на земле. И был человек тот знатнее всех, кто от востока солнца. Сходились же сыновья его друг к другу, делая пир на всякий день, забирая вместе с собою и трех сестер своих есть и пить с ними. И когда кончались дни пира, посылал Иов и очищал их, вставая рано утром, и приносил о них жертвы, по числу их, и одного тельца за грех о душах их. Ибо говорил Иов: «Не (согрешили ли) когда сыновья мои (и не) помыслили ли в уме своем дурного о Боге?» Так и делал Иов во все дни."},
  {"id": "ru-str-0199", "section": "service", "who": "priest", "text": "И как настал такой день – и вот, пришли Ангелы Божии предстать пред Господа; и диавол пришел с ними. И сказал Господь диаволу: «Откуда ты явился?» И в ответ диавол сказал Господу: «Обойдя землю и пройдя поднебесную, (вот,) я пришел». И сказал ему Господь: «Обратил ли ты мысль на слугу Моего Иова? Ибо нет подобного ему, среди тех, кто на земле: человек непорочный, [справедливый], правдивый, богобоязненный, удаляющийся от всякого злого дела». Отвечал (же) диавол и сказал пред Господом: «Разве даром Иов чтит Бога? Не Ты ли оградил что у него извне, и внутри дома его, и окрест всего, принадлежащего ему кругом? И дела рук его Ты благословил, и стада его сделал многочисленными на земле; но простри руку Твою и коснись всего, что он имеет, – конечно он в лицо [Твое] благословит Тебя!» Тогда сказал Господь диаволу: «Вот, всё, что есть у него, даю в руку твою; но к нему самому не прикоснись». И отошел диавол от [лица] Господня. Иов 1:1–12 Затем,"},
  {"id": "ru-str-0200", "section": "service", "who": "priest", "text": "Да исправится молитва моя:"},
  {"id": "ru-str-0201", "section": "service", "who": "priest", "text": "Евангелие от Матфея зачало 98"},
  {"id": "ru-str-0202", "section": "service", "who": "priest", "text": "В то время, когда сидел Иисус на горе Масличной, подошли к Нему ученики отдельно от других и спросили Его: скажи нам, когда это будет, и какое знамение Твоего пришествия и конца века? И ответил им Иисус: смотрите, чтобы кто не ввел вас в заблуждение. Ибо многие придут под именем Моим, говоря: «я Христос», и многих введут в заблуждение. Предстоит же вам в будущем слышать о войнах и военных слухах. Смотрите, не ужасайтесь; ибо это должно произойти, но это еще не конец. Ибо восстанет народ на народ и царство на царство, и будут голод и землетрясения по местам; все же это начало мук рождения. Тогда будут предавать вас на страдание и будут убивать вас; и вы будете ненавидимы всеми народами за имя Мое. И тогда соблазнятся многие; и будут друг друга предавать, и ненавидеть друг друга; и многие лжепророки восстанут и многих введут в заблуждение; и от умножения беззакония, во многих охладеет любовь. Претерпевший же до конца, тот будет спасен. И будет проповедано это Евангелие Царства по всей вселенной во свидетельство всем народам; и тогда придет конец. Итак, когда увидите мерзость запустения, ставшую на святом месте, о которой было сказано чрез Даниила пророка – читающий да разумеет, – тогда находящиеся в Иудее да бегут в горы; кто на крыше, да не спускается взять то, что в доме его; и кто в поле, да не возвращается взять одежду свою. Горе же имеющим во чреве и кормящим грудью в те дни. Молитесь, чтобы не случилось бегство ваше ни зимой, ни в субботу; ибо будет тогда великая скорбь, какой не было от начала мира доныне, и никогда не будет. И если бы не были сокращены дни те, не была бы спасена никакая плоть; но ради избранных будут сокращены дни те. Тогда, если кто вам скажет: «вот здесь Христос», или: «там», – не верьте; ибо восстанут лжехристы и лжепророки и произведут знамения великие и чудеса, чтобы ввести в заблуждение, если возможно, и избранных. Вот Я наперед сказал вам. Итак, если скажут вам: «вот Он в пустыне», – не выходите; «вот Он во внутренних покоях», – не верьте; ибо, как молния исходит от востока и светит до запада, так будет пришествие Сына Человеческого. Где будет труп, там соберутся орлы. Тотчас же, после скорби дней тех, солнце померкнет, и луна не даст света своего, и звезды упадут с неба, и силы небесные будут поколеблены. И тогда явится знамение Сына Человеческого на небе; и тогда будут бить себя в грудь все племена земные и увидят Сына Человеческого, грядущего на облаках небесных с силою и славою великою; и пошлет Он Ангелов Своих с трубою великой, и соберут избранных Его от четырех ветров, от края небес до края их. А образом да будет вам смоковница: когда ветвь ее становится уже мягкой и пускает листья, вы знаете, что близко лето. Так и вы, когда увидите все это, знайте, что близко, при дверях. Истинно говорю вам: не пройдет род сей, доколе все это не сбудется. Небо и земля пройдут, слова же Мои не пройдут. Мф 24:3–35"},
  {"id": "ru-str-0203", "section": "service", "who": "rubric", "text": "И прочее последование Литургии Преждеосвященных Даров. То же совершается и в Великий Вторник, и в Великую Среду."},
  {"id": "ru-str-0204", "section": "service", "who": "rubric", "text": "Если не служится Литургия, на"},
  {"id": "ru-str-0205", "section": "service", "who": "priest", "text": "Господи воззвах:"},
  {"id": "ru-str-0206", "section": "service", "who": "rubric", "text": "поем стихиры на 6. Стихира, глас 1:"},
  {"id": "ru-str-0207", "section": "service", "who": "priest", "text": "Господь, идя на добровольное страдание: (2),"},
  {"id": "ru-str-0208", "section": "service", "who": "priest", "text": "Достигнув, верные: (2),"},
  {"id": "ru-str-0209", "section": "service", "who": "priest", "text": "Не постигая несказанного таинства: (2)."},
  {"id": "ru-str-0210", "section": "service", "who": "priest", "text": "Слава, и ныне: Господи, шествуя на страдание:"},
  {"id": "ru-str-0211", "section": "service", "who": "rubric", "text": "Вход с Евангелием,"},
  {"id": "ru-str-0212", "section": "service", "who": "priest", "text": "Свет отрадный:"},
  {"id": "ru-str-0213", "section": "service", "who": "rubric", "text": "прокимен, и паримии, и Евангелие. Затем"},
  {"id": "ru-str-0214", "section": "service", "who": "priest", "text": "Сподоби Господи:"},
  {"id": "ru-str-0215", "section": "service", "who": "rubric", "text": "ектения просительная. На стиховне обычные стихи:"},
  {"id": "ru-str-0216", "section": "service", "who": "priest", "text": "К Тебе возвел я очи мои:"},
  {"id": "ru-str-0217", "section": "service", "who": "rubric", "text": "и стихиры, глас 8:"},
  {"id": "ru-str-0218", "section": "service", "who": "priest", "text": "Господи, совершеннейшим образом мудрствовать: (2) и глас 8:"},
  {"id": "ru-str-0219", "section": "service", "who": "priest", "text": "Устрашившись наказания, братия:"},
  {"id": "ru-str-0220", "section": "service", "who": "rubric", "text": "Слава, и ныне, глас тот же:"},
  {"id": "ru-str-0221", "section": "service", "who": "priest", "text": "Вторую Еву: Затем"},
  {"id": "ru-str-0222", "section": "service", "who": "priest", "text": "Ныне отпускаешь:"},
  {"id": "ru-str-0223", "section": "service", "who": "rubric", "text": "и прочее по уставу Великой Четыредесятницы."},
  {"id": "ru-str-0224", "section": "service", "who": "rubric", "text": "Так же совершается служба во Вторник и в Среду."},
  {"id": "ru-str-0225", "section": "service", "who": "rubric", "text": "На трапезе же в Великий Понедельник, Вторник и Среду довольствуемся сухоедением, как в первую седмицу Великого Поста."},
];

